mapper.sql:
SELECT -- ===== 岗位信息 exp_post ===== p.post_id AS postId, p.post_code AS postCode, p.post_name AS postName, p.post_type AS postType, p.post_level AS postLevel, p.post_category AS postCategory, p.status AS status, p.is_system AS isSystem, p.sort_no AS sortNo, DATE_FORMAT(p.created_time, '%Y-%m-%d %H:%i:%s') AS createdTime,
-- ===== 默认角色 exp_role ===== r.role_name AS defaultRoleName FROM exp_org_post_rel opr INNER JOIN exp_post p ON opr.post_id = p.post_id LEFT JOIN exp_role r ON p.default_role_id = r.role_id
opr.org_id = #{orgId}
opr.status = #{status}
ORDER BY opr.sort_no ASC, p.sort_no ASC
